import numpy as np, mujoco as mj, rcb_dtb as r
from scipy.spatial.transform import Rotation as Rot
class Controller:
 def __init__(self,s):
  self.s=s; self.m=s.model; self.d=mj.MjData(self.m); self.bid=self.m.body('palmleft_hand_C_MC').id
  self.jp=np.zeros((3,self.m.nv));self.jr=self.jp.copy()
 def fk(self,q):
  self.d.qpos[:]=self.s.data.qpos; self.d.qpos[self.s._jq]=q; mj.mj_forward(self.m,self.d)
  return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def ik(self,pos,rot,q=None,iters=80):
  q=self.s.state()['q'].copy() if q is None else q.copy()
  for _ in range(iters):
   p,R=self.fk(q); e=np.r_[pos-p,Rot.from_matrix(rot@R.T).as_rotvec()]
   if np.linalg.norm(e)<1e-5:break
   mj.mj_jacBody(self.m,self.d,self.jp,self.jr,self.bid)
   J=np.vstack([self.jp[:,:7],self.jr[:,:7]])
   dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   q[:7]+=dq*np.minimum(1,.15/max(np.max(abs(dq)),1e-8));q=np.clip(q,self.s.lower+.00001,self.s.upper-.00001)
  return q,float(np.linalg.norm(e))
 def move(self,pos,rot,hand=None,n=120):
  q0=self.s.targets.copy();q,err=self.ik(np.array(pos),rot,q0)
  if hand is not None:q[7:]=hand
  for t in range(n):
   a=(t+1)/n;a=a*a*(3-2*a);self.s.step(q0+(q-q0)*a)
  return err
 def pads(self,q):
  p,R=self.fk(q)
  out={}
  for f in ['thumb','index','middle','ring','pinky']:
   g=self.m.geom('palmleft_'+f+'_elastomer').id
   mid=self.m.geom_dataid[g];verts=self.m.mesh_vert[self.m.mesh_vertadr[mid]:self.m.mesh_vertadr[mid]+self.m.mesh_vertnum[mid]]
   v=verts.mean(0);v=self.d.geom_xmat[g].reshape(3,3)@v+self.d.geom_xpos[g]
   out[f]=R.T@(v-p)
  return out
