 x,y,z=center
 for f,inds,tgt in [('thumb',list(range(7,12)),[x,thumb_y,z-gap/2]),('index',list(range(12,16)),[x,-.0303,z+gap/2]),('middle',list(range(16,20)),[x,-.01,z+gap/2]),('ring',list(range(20,24)),[x,.0103,z+gap/2]),('pinky',list(range(24,29)),[x,.031,z+gap/2])]:
  def fun(v):
   qq=q.copy();qq[inds]=v;return np.r_[(c.pads(qq)[f]-tgt)*100,.015*(v-.6)]
  res=least_squares(fun,np.clip(np.full(len(inds),.5),c.s.lower[inds]+.0001,c.s.upper[inds]-.0001),bounds=(c.s.lower[inds]+1e-5,c.s.upper[inds]-1e-5),max_nfev=60)
  q[inds]=res.x
 return q[7:]

