 s.reset();s.record_start()
 center=np.array([par.get('cx',.055),0,par.get('cz',.125)])
 gap=par.get('gap',.026);h=posehand(c,center,gap,par.get('ty',-.015));ho=posehand(c,center,.065,par.get('ty',-.015))
 for _ in range(40):s.step(r.INIT_Q)
 obj=s.data.xpos[s._obj].copy();Ro=s.data.xmat[s._obj].reshape(3,3).copy()
 R=np.array([[0,1,0],[0,0,-1],[-1,0,0.]])
 if par.get('align',True):
  # y follows tool long axis projected to table
  y=Ro[:,0].copy();y[2]=0;y/=np.linalg.norm(y);x=np.array([0,0,-1]);R=np.stack([x,y,np.cross(x,y)],1)
 hc=obj+Ro@np.array([par.get('hx',-.025),0,0]);ptarget=hc-R@center
 c.move(ptarget+[0,0,.10],R,ho if par.get('preshape',True) else None,n=100)
 c.move(ptarget,R,n=120)
 q0=s.targets.copy();q1=q0.copy();q1[7:]=h
 for t in range(120):s.step(q0+(q1-q0)*min((t+1)/80,1))
 before=s.data.xpos[s._obj].copy();
 if render:
  from PIL import Image
  Image.fromarray(s.render_grid(size=(640,480))).save('/app/output/sweep_closed.png')
 c.move(ptarget+[0,0,.12],R,n=150)
 for _ in range(30):s.step(s.targets)
 after=s.data.xpos[s._obj].copy();score=after[2]-obj[2]
 if render:
  from PIL import Image
  Image.fromarray(s.render_grid(size=(640,480))).save('/app/output/sweep_lift.png')
 A=s.record_stop()
 return score,before,after,A
if __name__=='__main__':
 s=r.Session();c=Controller(s);best=-1
 if len(sys.argv)>1:
  par=json.loads(sys.argv[1]);out=run(s,c,par,True); print(par,out[:3]);s.save_trajectory(out[3],'/app/output/best_grasp.npz');sys.exit()
 for ps in [True,False]:
  for gap in [.032,.024,.016]:
