import numpy as np,rcb_dtb as r,mujoco as mj,json,sys
from scipy.optimize import least_squares
from scipy.spatial.transform import Rotation as Rot
from kin import Controller
from PIL import Image
s=r.Session();c=Controller(s)
def makehand(center,par):
 q=r.INIT_Q.copy();x,y,z=center
 for f,inds,tgt in [('thumb',list(range(7,12)),[x,y-par.get('gap',.03)/2,z]),('index',list(range(12,16)),[x,y+par.get('gap',.03)/2,z+.025]),('middle',list(range(16,20)),[x,y+par.get('gap',.03)/2,z+.035]),('ring',list(range(20,24)),[x,y+.02,z+.02]),('pinky',list(range(24,29)),[x,y+.04,z])]:
  def fun(v):
   qq=q.copy();qq[inds]=v;return np.r_[(c.pads(qq)[f]-tgt)*100,.04*(v-.6)]
  res=least_squares(fun,np.clip(np.full(len(inds),.5),s.lower[inds]+1e-4,s.upper[inds]-1e-4),bounds=(s.lower[inds]+1e-5,s.upper[inds]-1e-5),max_nfev=70);q[inds]=res.x
 return q[7:]
def run(par,render=False):
 s.reset();s.record_start();center=np.array([par.get('cx',.06),par.get('cy',-.03),par.get('cz',.13)])
 hand=makehand(center,par);ho=hand.copy();ho[0]=.3;ho[5]=0;ho[9]=0;ho[13]=0;ho[18]=0
 for _ in range(40):s.step(r.INIT_Q)
 op=s.data.xpos[s._obj].copy();oR=s.data.xmat[s._obj].reshape(3,3).copy()
 z=oR[:,0].copy();z[2]=0;z/=np.linalg.norm(z);z*=par.get('sign',1)
 x=np.array([0,0,-1]);R=np.stack([x,np.cross(z,x),z],1)
 hc=op+oR@np.array([par.get('hx',-.02),0,0]);tp=hc-R@center
 c.move(tp+[0,0,.12],R,ho,n=150);c.move(tp,R,n=180)
 q0=s.targets.copy();q1=q0.copy();q1[7:]=hand
 for t in range(180):s.step(q0+(q1-q0)*min((t+1)/100,1))
 if render:Image.fromarray(s.render_grid(size=(640,480))).save('/app/output/axial_closed.png')
 c.move(tp+[0,0,.13],R,n=180)
 if render:Image.fromarray(s.render_grid(size=(640,480))).save('/app/output/axial_lift.png')
 prev=-1
 for t in range(18000):
  if s.goal_index>=76 or s.failed:break
  op=s.data.xpos[s._obj].copy();oR=s.data.xmat[s._obj].reshape(3,3).copy();pp=s.data.xpos[c.bid].copy();pR=s.data.xmat[c.bid].reshape(3,3).copy()
  if op[2]<.60:break
  goal=np.array(s.goals[s.goal_index]);gp=goal[:3];gR=r._quat_to_mat_wxyz(r.wxyz(goal));er=Rot.from_matrix(gR@oR.T).as_rotvec();ep=gp-op
  frac=min(1,.001/(np.linalg.norm(ep)+1e-10),.006/(np.linalg.norm(er)+1e-10));dR=Rot.from_rotvec(frac*er).as_matrix()
  q,err=c.ik(op+frac*ep+dR@(pp-op),dR@pR,s.state()['q'],iters=4);q[7:]=hand;s.step(q)
  if render and s.goal_index!=prev:print(t,s.progress(),flush=True);prev=s.goal_index
 A=s.record_stop();return s.goal_index,A
if len(sys.argv)>1:
 par=json.loads(sys.argv[1]);k,A=run(par,True);print(par,k,flush=True);s.save_trajectory(A,'/app/output/axial_try.npz')
else:
 best=0
 for sign in [1,-1]:
  for cy in [-.04,-.02,0]:
   for gap in [.015,.025,.035]:
    for cx in [.04,.055,.07]:
     par=dict(sign=sign,cy=cy,gap=gap,cx=cx)
     k,A=run(par);print(par,k,flush=True)
     if k>best:best=k;s.save_trajectory(A,'/app/output/axial_best.npz');json.dump(par,open('/app/output/axial_par.json','w'))
     if k>=76:sys.exit()
PY
